// exactly that latitude: a member claims nothing at file scope.
func (b *ConvergeStateBlock) StreamsStride() int64           { return 104 }
func (b *ConvergeStateBlock) StreamsMax() int64              { return 16 }
func (b *ConvergeStateBlock) StreamsProjectionOffset() int64 { return 24 }

// Streams is ITERATED, not indexed by hand: the accessor points at each row where
// it lies, at the pitch the INSTANCE gives, for the count the instance gives.
func (b *ConvergeStateBlock) Streams() TableBlockRows[ConvergeStreamEntryRow] {
	return TableBlockRows[ConvergeStreamEntryRow]{
		Base:   unsafe.Add(b.Base, uintptr(b.Projection.Streams.OffsetOf)),
		Count:  int32(b.Projection.Streams.Count),
		Stride: int32(b.Projection.Streams.Stride),
	}
}

// StreamsSpan is the CONTIGUOUS view, available because the pitch IS the
// element's size (§2.7), which is how the per-frame fast path is written.
func (b *ConvergeStateBlock) StreamsSpan() []ConvergeStreamEntryRow {
	return unsafe.Slice((*ConvergeStreamEntryRow)(unsafe.Add(b.Base, uintptr(b.Projection.Streams.OffsetOf))), b.Projection.Streams.Count)
}

// ---- block fill path: end ----
// ConvergeStateBlockOpen is the bool convenience for the handle's typed Open error.
func ConvergeStateBlockOpen(block *ConvergeStateBlock, base unsafe.Pointer, bytes int64) bool {
	return block.Open(base, bytes) == nil
}

// Open reads all prologue and layout words bytewise before the final base
// alignment check. Every refusal names the first failed clause in SPEC §19.2.
func (block *ConvergeStateBlock) Open(base unsafe.Pointer, bytes int64) error {
	*block = ConvergeStateBlock{}
	if base == nil {
		return TableRefuseUnalignedBase
	}
	if bytes < 40 {
		return TableRefuseTruncated
	}
	header := unsafe.Slice((*byte)(base), 40)
	magic := binary.NativeEndian.Uint64(header)
	if magic != TableBlockMagic {
		if magic == 0x5343484d41424c4b {
			return TableRefuseForeignOrder
		}
		return TableRefuseNotACook
	}
	if binary.NativeEndian.Uint64(header[16:]) != TableBlockByteOrder {
		return TableRefuseNotACook
	}
	if binary.NativeEndian.Uint64(header[8:]) != BuildVersion {
		return TableRefuseWrongBuildVersion
	}
	used := int64(40)
	{
		// EVERY NUMBER BELOW COMES FROM THE INSTANCE, so the arithmetic is
		// unsigned and each term is BOUNDED BEFORE IT IS ADDED. A forged
		// OffsetOf near 2^63 must refuse, and an addition that wrapped past the
		// top of the type would be what the check after it was supposed to
		// catch. The C++ side holds the same shape for the same reason.
		triple := header[unsafe.Offsetof(ConvergeStateBlockProjection{}.Streams):]
		offsetOf := binary.NativeEndian.Uint64(triple)
		count := uint64(binary.NativeEndian.Uint32(triple[8:]))
		stride := uint64(binary.NativeEndian.Uint32(triple[12:]))
		if stride != uint64(unsafe.Sizeof(ConvergeStreamEntryRow{})) {
			return TableRefuseBadLayout
		}
		// past the DECLARED MAXIMUM: the producer side refuses this too, because
		// a consumer that sizes anything by the maximum would overflow on a
		// count the maximum does not bound
		if count > 16 {
			return TableRefuseBadLayout
		}
		if offsetOf < 40 || offsetOf%64 != 0 {
			return TableRefuseBadLayout
		}
		if offsetOf > uint64(bytes) {
			return TableRefuseBadLayout
		}
		rows := count * stride // both bounded above: this cannot carry
		if rows > uint64(bytes)-offsetOf {
			return TableRefuseBadLayout
		}
		if end := int64(offsetOf + rows); end > used {
			used = end
		}
	}
	padding := (64 - (used % 64)) % 64
	if padding > bytes-used {
		return TableRefuseTruncated
	}
	used += padding
	if uintptr(base)%64 != 0 {
		return TableRefuseUnalignedBase
	}
	block.Base = base
	block.Projection = (*ConvergeStateBlockProjection)(base)
	block.Bytes = used
	return nil
}

// ConvergeStateCounts is gathered before Begin; clamping is the caller's policy.
type ConvergeStateCounts struct {
	Streams int32
}

// ConvergeStateBlockStorage owns a maximum-sized extent. Do not copy an initialized storage.
type ConvergeStateBlockStorage struct {
	base       unsafe.Pointer
	allocation []byte
	allocator  TableBlockAllocator
}

func (s *ConvergeStateBlockStorage) Create(a TableBlockAllocator) bool {
	if s == nil || s.allocation != nil || a.Alloc == nil || a.Free == nil {
		return false
	}
	raw := a.Alloc(ConvergeStateBlockMaxBytes + 63)
	if int64(len(raw)) < ConvergeStateBlockMaxBytes+63 {
		if raw != nil {
			a.Free(raw)
		}
		return false
	}
	s.allocation = raw
	s.allocator = a
	offset := (-uintptr(unsafe.Pointer(&raw[0]))) & 63
	s.base = unsafe.Pointer(&raw[offset])
	return true
}
func (s *ConvergeStateBlockStorage) Destroy() {
	if s != nil && s.allocation != nil {
		s.allocator.Free(s.allocation)
		*s = ConvergeStateBlockStorage{}
	}
}

// ---- block fill path: begin ----
// ConvergeStateBlockBegin writes only the prologue and triples, never rows or padding.
// Storage and all counts are checked before any byte of the extent changes.
func ConvergeStateBlockBegin(b *ConvergeStateBlock, s *ConvergeStateBlockStorage, c ConvergeStateCounts, refusal *TableBlockRefusal) bool {
	if refusal != nil {
		*refusal = TableBlockRefusal{}
	}
	if b == nil {
		return false
	}
	if c.Streams < 0 || c.Streams > 16 {
		if refusal != nil {
			*refusal = TableBlockRefusal{Array: "streams", Count: int64(c.Streams), Maximum: 16}
		}
		return false
	}
	if s == nil || s.base == nil {
		return false
	}
	p := (*ConvergeStateBlockProjection)(s.base)
	p.Magic = TableBlockMagic
	p.BuildVersion = BuildVersion
	p.ByteOrder = TableBlockByteOrder
	offset := int64(40)
	offset = (offset + 63) &^ int64(63)
	p.Streams = TableBlockTriple{OffsetOf: uint64(offset), Count: uint32(c.Streams), Stride: 104}
	offset += int64(c.Streams) * 104
	*b = ConvergeStateBlock{Base: s.base, Projection: p, Bytes: (offset + 63) &^ int64(63)}
	return true
}

func ConvergeStateBlockBytes(b *ConvergeStateBlock) int64 {
	if b == nil || b.Projection == nil {
		return 0
	}
	used := int64(40)
	if end := int64(b.Projection.Streams.OffsetOf) + int64(b.Projection.Streams.Count)*int64(b.Projection.Streams.Stride); end > used {
		used = end
	}
	return (used + 63) &^ int64(63)
}

// ---- block fill path: end ----

// Type is this block's descriptors: constant data, so a reflective read costs
// a lookup and not a parse. The row layouts hang off the element column
// rather than taking names of their own, so a walker reaches every record
// through the graph.
func (b *ConvergeStateBlock) Type() *TableBlockInfo { return &tableBlockRecords[0] }
